; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcfw (Amstrad CPC - firmware text and keys), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 1		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)

ntc_start:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			di				; (KL ROM SELECT lets interrupts in again)
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; 9: Cls
			dw kw_cls

			; 10: Print "VB self test 8"
			dw kw_printstrvar, str0
			dw kw_printnl

			; 13: table(0) = AddressOf AddOne
			dw kw_vtov, ap_p_addone_c, arr_table

			; 14: table(1) = AddressOf AddTen
			dw kw_vtov, ap_p_addten_c, arr_table+2

			; 15: table(2) = AddressOf AddArg
			dw kw_vtov, ap_p_addarg_c, arr_table+4

			; 16: total = 0
			dw kw_ztov, var_total

			; 17: CallAddr table(0)
			dw kw_callp, arr_table

			; 18: CallAddr table(1)
			dw kw_callp, arr_table+2

			; 19: Chk total, 11
			dw p_chk_c, var_total, lit_11

			; 20: p = table(2)
			dw kw_vtov, arr_table+4, var_p

			; 21: CallAddr p, 100
			dw kw_ltov, 100, tmp1
			dw kw_callp, var_p, tmp1

			; 22: Chk total, 111
			dw p_chk_c, var_total, lit_111

			; 23: For i = 0 To 1
			dw kw_ztov, var_i
for1_t:

			; 24: CallAddr table(i)
			dw kw_aget, arr_table, var_i, tmp0
			dw kw_callp, tmp0

			; 25: Next
			dw kw_next1l_n, var_i, 1, for1_t
for1_e:

			; 26: Chk total, 122
			dw p_chk_c, var_total, lit_122

			; 27: i = 5
			dw kw_ltov, 5, var_i

			; 28: CallAddr table(2), i * 2
			dw kw_2x, var_i, tmp1
			dw kw_callp, arr_table+4, tmp1

			; 29: Chk total, 132
			dw p_chk_c, var_total, lit_132

			; 30: Register AddressOf AddTen
			dw p_register_c, ap_p_addten_c

			; 31: Chk total, 142
			dw p_chk_c, var_total, lit_142

			; 33: Print
			dw kw_printnl

			; 34: Print t; " tests, "; bad; " failed"
			dw kw_printint, var_t
			dw kw_printstrvar, str1
			dw kw_printint, var_bad
			dw kw_printstrvar, str2
			dw kw_printnl

			; 35: Print "Press a key";
			dw kw_printstrvar, str3

			; 36: Do : Frame : Loop Until Inkey <> 0
do2_t:
			dw kw_frame
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do2_t
do2_e:

			; 37: Print
			dw kw_printnl

			; 38: End
			dw kw_stop

; ============================================================
; sub chk (normal mode)
; ============================================================

p_chk:

			; 41: t = t + 1
			dw kw_inc, var_t

			; 42: Print t; ":";
			dw kw_printint, var_t
			dw kw_printstrvar, str4

			; 43: If got = want Then
			dw kw_cpeqvv, var_chk_got, var_chk_want
			dw kw_goto_iffalse_n, if3_1

			; 44: Print "ok ";
			dw kw_printstrvar, str5

			; 45: Else
			dw if3_e_go
if3_1:

			; 46: Print "FAIL("; got; ") ";
			dw kw_printstrvar, str6
			dw kw_printint, var_chk_got
			dw kw_printstrvar, str7

			; 47: bad = bad + 1
			dw kw_inc, var_bad

			; 48: End If
if3_e:
			dw p_chk_r

; ============================================================
; sub addone (normal mode)
; ============================================================

p_addone:

			; 52: total = total + 1
			dw kw_inc, var_total
			dw p_addone_r

; ============================================================
; sub addten (normal mode)
; ============================================================

p_addten:

			; 56: total = total + 10
			dw kw_addl, var_total, 10, var_total
			dw p_addten_r

; ============================================================
; sub addarg (normal mode)
; ============================================================

p_addarg:

			; 60: total = total + n
			dw kw_add, var_total, var_addarg_n, var_total
			dw p_addarg_r

; ============================================================
; sub register (normal mode)
; ============================================================

p_register:

			; 65: CallAddr entry
			dw kw_callp, var_register_entry
			dw p_register_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if3_e_go:			ld sp, if3_e
			jp ntc_xn

p_chk_c:		; call chk (normal)
			pop hl			; got
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_got), de
			pop hl			; want
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_want), de
			ld (p_chk_rs), sp
			ld sp, p_chk
			jp ntc_xn
p_chk_r:		; end of chk
			ld sp, (p_chk_rs)
			jp ntc_xn
p_addone_c:		; call addone (normal)
			ld (p_addone_rs), sp
			ld sp, p_addone
			jp ntc_xn
p_addone_r:		; end of addone
			ld sp, (p_addone_rs)
			jp ntc_xn
p_addten_c:		; call addten (normal)
			ld (p_addten_rs), sp
			ld sp, p_addten
			jp ntc_xn
p_addten_r:		; end of addten
			ld sp, (p_addten_rs)
			jp ntc_xn
p_addarg_c:		; call addarg (normal)
			pop hl			; n
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_addarg_n), de
			ld (p_addarg_rs), sp
			ld sp, p_addarg
			jp ntc_xn
p_addarg_r:		; end of addarg
			ld sp, (p_addarg_rs)
			jp ntc_xn
p_register_c:		; call register (normal)
			pop hl			; entry
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_register_entry), de
			ld (p_register_rs), sp
			ld sp, p_register
			jp ntc_xn
p_register_r:		; end of register
			ld sp, (p_register_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_total:			dw 0
var_p:			dw 0
var_i:			dw 0
var_t:			dw 0
var_bad:			dw 0
p_chk_rs:			dw 0
var_chk_got:			dw 0
var_chk_want:			dw 0
p_addone_rs:			dw 0
p_addten_rs:			dw 0
p_addarg_rs:			dw 0
var_addarg_n:			dw 0
p_register_rs:			dw 0
var_register_entry:			dw 0
tmp0:			dw 0
tmp1:			dw 0

; numbers passed by address (read only)
ap_p_addone_c:			dw p_addone_c
ap_p_addten_c:			dw p_addten_c
ap_p_addarg_c:			dw p_addarg_c
lit_11:			dw 11
lit_111:			dw 111
lit_122:			dw 122
lit_132:			dw 132
lit_142:			dw 142

; ============================================================
; Strings
; ============================================================

str0:			db "VB self test 8", 0
str1:			db " tests, ", 0
str2:			db " failed", 0
str3:			db "Press a key", 0
str4:			db ":", 0
str5:			db "ok ", 0
str6:			db "FAIL(", 0
str7:			db ") ", 0

; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the ROM NTC CPCFW (NTCFW.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_goto_iffalse_n:	jp 11
kw_next1l_n:	jp 31
kw_ltov:		jp 47
kw_vtov:		jp 48
kw_ztov:		jp 49
kw_inc:		jp 51
kw_add:		jp 53
kw_addl:		jp 54
kw_2x:		jp 57
kw_cpeqvv:	jp 95
kw_cpnevl:	jp 98
kw_aget:		jp 111
kw_printstrvar:	jp 129
kw_printint:	jp 131
kw_callp:	jp 135
kw_printnl:	jp 138
kw_inkey:	jp 144
kw_cls:		jp 147
kw_frame:	jp 152
kw_bssinit:	jp 288
NTC_RJ_N	equ 22		; entries
ntc_csp	equ #8800		; ROM data
ntc_nmode	equ #8807		; ROM data
ntc_v_free	equ #894E		; ROM data
ntc_v_romen	equ #8954		; ROM data
ntc_v_romold	equ #8956		; ROM data
ntc_v_stamp	equ #8952		; ROM data
ntc_v_start	equ #8950		; ROM data
			ASSERT ntc_free <= #8800, "Library: ROM - the program and its arrays must end below #8800 (the ROM's RAM)"

; the start: find the ROM set in slots 0 - 31 (its main ROM, then the others with the same
; stamp), have the main one patch the jump block. NC = ready; C = not there / too old
; (the message is shown, the caller's ROM selection is back)
ntc_rj_find:
			ld c, 0
			call #B90F		; KL ROM SELECT: B / C = the caller's state and selection
			ld (ntc_rj_old), bc
			xor a
			ld (ntc_rj_want), a
			call ntc_rj_scan		; the main ROM
			jp c, ntc_rj_nf
			ld (ntc_rj_slots), a
			ld e, (hl)
			inc hl
			ld d, (hl)			; its patcher
			ld (ntc_rj_call + 1), de
			ld a, 1
ntc_rj_more:				; the other ROMs of the set
			ld (ntc_rj_want), a
			ld hl, ntc_rj_n
			cp (hl)
			jr nc, ntc_rj_all
			call ntc_rj_scan
			jp c, ntc_rj_part
			ld b, a
			ld a, (ntc_rj_want)
			ld e, a
			ld d, 0
			ld hl, ntc_rj_slots
			add hl, de
			ld (hl), b
			inc a
			jr ntc_rj_more
ntc_rj_all:
			ld a, (ntc_rj_slots)
			ld c, a
			call #B90F		; KL ROM SELECT: the main ROM
			di					; (KL ROM SELECT lets interrupts in)
			ld a, (ntc_rj_slots)	; its slot
			ld hl, ntc_rj_block
			ld bc, NTC_RJ_N
			ld de, ntc_rj_slots
ntc_rj_call:
			call 0				; HL = jump block, BC = entries, A = slot, DE = slots; C: DE = a number it hasn't got
			jp c, ntc_rj_lacks
			ld hl, ntc_free
			ld (ntc_v_free), hl
			ld hl, ntc_start
			ld (ntc_v_start), hl
			ld hl, 0
			ld (ntc_v_stamp), hl
			ld a, 0
			ld (ntc_v_romen), a
			ld a, (ntc_rj_old)
			ld (ntc_v_romold), a
			or a				; NC: ready
			ret
; ntc_rj_scan - a ROM of the set: ROM ntc_rj_want (0 = the main one, any stamp; the others
; with the main one's stamp). NC: A = its slot, HL = past its block's count byte (the main
; one: at its patcher), it is selected. C: not there
ntc_rj_scan:
			ld c, 0
ntc_rj_next:
			push bc
			call #B90F		; KL ROM SELECT: ROM C
			pop bc
			ld a, (#C000)
			cp 1				; a background ROM?
			jr nz, ntc_rj_skip
			ld hl, (#C004)		; its names
			ld a, h
			cp #C0
			jr c, ntc_rj_skip
ntc_rj_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, ntc_rj_name		; to the 0 after the names
			ld de, ntc_rj_sig
			ld b, ntc_rj_sige - ntc_rj_sig
ntc_rj_cmp:
			ld a, (de)
			cp (hl)
			jr nz, ntc_rj_skip
			inc de
			inc hl
			djnz ntc_rj_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)			; DE = its set's stamp
			inc hl
			ld a, (ntc_rj_want)
			cp (hl)				; its place in the set
			jr nz, ntc_rj_skip
			or a
			jr z, ntc_rj_got
			push hl
			ld hl, (ntc_rj_set)
			or a
			sbc hl, de
			pop hl
			jr nz, ntc_rj_skip		; another build's
ntc_rj_got:
			ld (ntc_rj_set), de
			inc hl
			ld a, (hl)
			ld (ntc_rj_n), a		; ROMs in the set
			inc hl
			ld a, c
			or a				; NC
			ret
ntc_rj_skip:
			inc c
			ld a, c
			cp 32
			jr c, ntc_rj_next
			scf					; C: not there
			ret
ntc_rj_nf:
			ld hl, ntc_rj_tnf
			jr ntc_rj_fail
ntc_rj_part:				; a ROM of the set is missing: its number (1 = the main one)
			ld a, (ntc_rj_want)
			inc a
			ld e, a
			ld d, 0
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tpt
			jr ntc_rj_fnum
ntc_rj_lacks:
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tlk
ntc_rj_fnum:
			ld a, 1
			ld (ntc_rj_pn), a		; the number after the message
ntc_rj_fail:
			push hl
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT: the caller's selection again
			pop hl
			call ntc_rj_puts
			ld a, (ntc_rj_pn)
			or a
			jr z, ntc_rj_nl
			ld a, (ntc_rj_num + 1)
			call ntc_rj_hex
			ld a, (ntc_rj_num)
			call ntc_rj_hex
ntc_rj_nl:
			ld hl, ntc_rj_tnl
			call ntc_rj_puts
			ei
			call #BB06		; KM WAIT CHAR: a key first (a RUN" program's return resets the machine)
			di
			scf
			ret
ntc_rj_puts:				; HL = text, 0 ends; DE = its start
			ld d, h
			ld e, l
ntc_rj_pl:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_rj_pl
ntc_rj_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_rj_dig
			pop af
ntc_rj_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
; End: the caller's ROM selection again, then back to the caller
ntc_rj_exit:
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT
			ret
ntc_rj_old:		dw 0			; the caller's ROM selection (C) and state (B)
ntc_rj_num:		dw 0
ntc_rj_pn:		db 0			; 1 = a number goes after the message
ntc_rj_want:	db 0			; the ROM of the set looked for
ntc_rj_n:		db 1			; ROMs in the set
ntc_rj_set:		dw 0			; the set's stamp
ntc_rj_slots:	ds 8			; each ROM's slot, the main one first
ntc_rj_sig:		db "NTC", 2, "CPCFW", 0	; the ROMs' NTC block
ntc_rj_sige:
ntc_rj_tnf:		db "ROM NTC CPCFW (NTCFW.ROM) not found", 0
ntc_rj_tlk:		db "ROM NTC CPCFW too old: no routine #", 0
ntc_rj_tpt:		db "ROM NTCFW<n>.ROM not found: n = #", 0
ntc_rj_tnl:		db 13, 10, "Press a key", 13, 10, 0

ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bss		equ ntc_end
arr_table		equ ntc_bss + 0		; 6 bytes
ntc_bss_size	equ 6
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
			SAVEAMSDOS "VBTEST8.BIN", ntc_start, ntc_end - ntc_start, ntc_start
